def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("TC-141 准备查询失败：GET /communities 预期 HTTP 200、业务码 0；缺少制造接受邀请中途写入失败的 HTTP 接口，目标场景仍阻塞")
    assert responseBody.get("requestId")
    if not isinstance(responseBody.get("data"), list):
        raise Blocked("TC-141 社区查询数据不可用；缺少制造接受邀请中途写入失败的 HTTP 接口，目标场景仍阻塞")
    raise Blocked("TC-141 已核查公开 GET /communities（HTTP 200、业务码 0、requestId 非空）；公开契约没有制造接受邀请中途写入失败的 HTTP 接口，正常接受、重复接受和参数错误不能代替中途故障；接受邀请中途失败整体回滚的前提构造与目标核查均无法通过公开 HTTP 完成，查询成功不得判定目标场景通过")
